fn findRangeRecordPtr(
    ranges: []const *const metadata_table_manager.RangeRecord,
    group_id: u64,
) ?*const metadata_table_manager.RangeRecord {
    for (ranges) |range| {
        if (range.group_id == group_id) return range;
    }
    return null;
}

