fn publishRuntimeStatusGroupForTest(
    cache: *runtime_status.TableRuntimeSnapshotCache,
    table_name: []const u8,
    status: runtime_status.LocalTableRuntimeStatus,
) !void {
    const token = try cache.capturePublicationToken(table_name);
    try std.testing.expectEqual(
        runtime_status.TableRuntimeSnapshotCache.PublishResult.published,
        try cache.publishGroup(token, table_name, status),
    );
}

fn publishRuntimeStatusRefreshForTest(
    cache: *runtime_status.TableRuntimeSnapshotCache,
    snapshots: []runtime_status.TableRuntimeSnapshot,
) !void {
    var ownership_transferred = false;
    errdefer if (!ownership_transferred) {
        for (snapshots) |*snapshot_entry| snapshot_entry.deinit(cache.alloc);
    };
    const table_names = try cache.alloc.alloc([]const u8, snapshots.len);
    defer cache.alloc.free(table_names);
    for (snapshots, 0..) |snapshot_entry, i| table_names[i] = snapshot_entry.table_name;
    var token = try cache.captureCatalogToken(cache.alloc, table_names, true);
    defer token.deinit();
    ownership_transferred = true;
    var result = try cache.publishRefresh(&token, snapshots);
    defer result.deinit();
    try std.testing.expect(!result.hasRejectedTables());
}

fn isTransientWriterOpenConflict(err: anyerror) bool {
    return err == error.LsmRootWriterAlreadyOpen or err == error.WriterLocked;
}

fn mergeDocumentArtifactTableReprocessResult(
    alloc: std.mem.Allocator,
    dst: *db_mod.types.DocumentArtifactTableReprocessResult,
    dst_failures: *std.ArrayListUnmanaged(db_mod.types.DocumentArtifactReprocessFailure),
    dst_shard_cursors: *std.ArrayListUnmanaged(db_mod.types.DocumentArtifactReprocessShardCursor),
    group_id: ?u64,
    src: db_mod.types.DocumentArtifactTableReprocessResult,
) !void {
    dst.scanned += src.scanned;
    dst.reprocessed += src.reprocessed;
    dst.skipped += src.skipped;
    dst.failed += src.failed;
    dst.limit += src.limit;
    if (dst.next_key == null) {
        if (src.next_key) |next_key| dst.next_key = try alloc.dupe(u8, next_key);
    }
    if (src.shard_cursors.len > 0) {
        for (src.shard_cursors) |cursor| {
            const next_key_copy = try alloc.dupe(u8, cursor.next_key);
            errdefer alloc.free(next_key_copy);
            try dst_shard_cursors.append(alloc, .{
                .group_id = cursor.group_id orelse group_id,
                .next_key = next_key_copy,
                .scanned = cursor.scanned,
                .reprocessed = cursor.reprocessed,
                .skipped = cursor.skipped,
                .failed = cursor.failed,
                .limit = cursor.limit,
            });
        }
    } else if (src.next_key) |next_key| {
        const next_key_copy = try alloc.dupe(u8, next_key);
        errdefer alloc.free(next_key_copy);
        try dst_shard_cursors.append(alloc, .{
            .group_id = group_id,
            .next_key = next_key_copy,
            .scanned = src.scanned,
            .reprocessed = src.reprocessed,
            .skipped = src.skipped,
            .failed = src.failed,
            .limit = src.limit,
        });
    }
    for (src.failures) |failure| {
        const key = try alloc.dupe(u8, failure.key);
        errdefer alloc.free(key);
        const error_code = try alloc.dupe(u8, failure.error_code);
        errdefer alloc.free(error_code);
        try dst_failures.append(alloc, .{
            .key = key,
            .error_code = error_code,
        });
    }
}

fn documentArtifactReprocessRequestForCursor(
    req: db_mod.types.DocumentArtifactTableReprocessRequest,
    cursor: db_mod.types.DocumentArtifactReprocessShardResume,
) db_mod.types.DocumentArtifactTableReprocessRequest {
    return .{
        .from_key = cursor.next_key,
        .to_key = req.to_key,
        .limit = if (cursor.limit != 0) cursor.limit else req.limit,
    };
}

fn parseDocumentArtifactTableReprocessResultAlloc(alloc: std.mem.Allocator, body: []const u8) !db_mod.types.DocumentArtifactTableReprocessResult {
    const RemoteFailure = struct {
        key: []const u8,
        error_code: []const u8,
    };
    const RemoteShardCursor = struct {
        group_id: ?u64 = null,
        next_key: []const u8,
        scanned: usize = 0,
        reprocessed: usize = 0,
        skipped: usize = 0,
        failed: usize = 0,
        limit: u32 = 0,
    };
    const RemoteResult = struct {
        scanned: usize = 0,
        reprocessed: usize = 0,
        skipped: usize = 0,
        failed: usize = 0,
        limit: u32 = 0,
        next_key: ?[]const u8 = null,
        failures: []const RemoteFailure = &.{},
        shard_cursors: []const RemoteShardCursor = &.{},
    };

    var parsed = try std.json.parseFromSlice(RemoteResult, alloc, body, .{});
    defer parsed.deinit();

    var failures = try alloc.alloc(db_mod.types.DocumentArtifactReprocessFailure, parsed.value.failures.len);
    var initialized: usize = 0;
    errdefer {
        for (failures[0..initialized]) |*failure| failure.deinit(alloc);
        if (failures.len > 0) alloc.free(failures);
    }
    for (parsed.value.failures, failures) |remote, *out| {
        out.* = .{
            .key = try alloc.dupe(u8, remote.key),
            .error_code = try alloc.dupe(u8, remote.error_code),
        };
        initialized += 1;
    }

    var shard_cursors = try alloc.alloc(db_mod.types.DocumentArtifactReprocessShardCursor, parsed.value.shard_cursors.len);
    var initialized_cursors: usize = 0;
    errdefer {
        for (shard_cursors[0..initialized_cursors]) |*cursor| cursor.deinit(alloc);
        if (shard_cursors.len > 0) alloc.free(shard_cursors);
    }
    for (parsed.value.shard_cursors, shard_cursors) |remote, *out| {
        out.* = .{
            .group_id = remote.group_id,
            .next_key = try alloc.dupe(u8, remote.next_key),
            .scanned = remote.scanned,
            .reprocessed = remote.reprocessed,
            .skipped = remote.skipped,
            .failed = remote.failed,
            .limit = remote.limit,
        };
        initialized_cursors += 1;
    }

    return .{
        .scanned = parsed.value.scanned,
        .reprocessed = parsed.value.reprocessed,
        .skipped = parsed.value.skipped,
        .failed = parsed.value.failed,
        .limit = parsed.value.limit,
        .next_key = if (parsed.value.next_key) |value| try alloc.dupe(u8, value) else null,
        .failures = failures,
        .shard_cursors = shard_cursors,
    };
}

fn appendOwnedArtifactRepairIssues(
    alloc: std.mem.Allocator,
    out: *std.ArrayListUnmanaged(db_mod.types.ArtifactRepairIssue),
    issues: []db_mod.types.ArtifactRepairIssue,
) !void {
    var moved: usize = 0;
    errdefer {
        for (issues[moved..]) |*issue| issue.deinit(alloc);
        if (issues.len > 0) alloc.free(issues);
    }
    for (issues) |*issue| {
        try out.append(alloc, issue.*);
        issue.* = undefined;
        moved += 1;
    }
    if (issues.len > 0) alloc.free(issues);
}

fn mergeArtifactRepairResult(dst: *db_mod.types.ArtifactRepairResult, src: db_mod.types.ArtifactRepairResult) void {
    dst.scanned += src.scanned;
    dst.groups_scanned += src.groups_scanned;
    dst.reprocessed += src.reprocessed;
    dst.repaired += src.repaired;
    dst.missing_source_docs += src.missing_source_docs;
    dst.failed += src.failed;
    dst.unsupported += src.unsupported;
    dst.unresolved += src.unresolved;
    dst.in_progress += src.in_progress;
    dst.indexes_rebuilt += src.indexes_rebuilt;
    dst.indexes_degraded += src.indexes_degraded;
    dst.controls_applied += src.controls_applied;
    dst.debt_remaining = dst.debt_remaining or src.debt_remaining;
}

const ArtifactRepairTableCursor = struct {
    group_id: u64,
    local_cursor: []const u8,
};

fn parseArtifactRepairTableCursor(cursor: ?[]const u8) !?ArtifactRepairTableCursor {
    const raw = cursor orelse return null;
    if (raw.len == 0) return null;
    const sep = std.mem.indexOfScalar(u8, raw, ':') orelse return error.InvalidArgument;
    const group_id = try std.fmt.parseUnsigned(u64, raw[0..sep], 10);
    return .{ .group_id = group_id, .local_cursor = raw[sep + 1 ..] };
}

fn formatArtifactRepairTableCursorAlloc(alloc: std.mem.Allocator, group_id: u64, local_cursor: ?[]const u8) ![]u8 {
    return try std.fmt.allocPrint(alloc, "{d}:{s}", .{ group_id, local_cursor orelse "" });
}

