    fn finishLocalStructuralCachedDbMutation(self: *ProvisionedTableWriteSource, table_name: []const u8) void {
        lockAtomic(&self.local_db_mutex);
        self.invalidateReadCache(table_name);
        self.local_db_mutex.unlock();
