fn tryPublishRuntimeStatusSnapshotConsistent(
    source: *ProvisionedTableWriteSource,
    alloc: std.mem.Allocator,
    table_name: []const u8,
    group_id: u64,
    db: *db_mod.DB,
) !bool {
    publishRuntimeStatusSnapshotConsistentIfAvailable(
        source,
        alloc,
        table_name,
        group_id,
