            },
            .{
                .key = "doc:b",
                .value = "{\"filename\":\"delta.txt\",\"mime_type\":\"text/plain\",\"version\":\"1\",\"url\":\"data:text/plain;base64,ZGVsdGEgZXBzaWxvbg==\"}",
