    try std.testing.expect(owner.isWriteCacheDirtyForTable("docs"));
    try std.testing.expect(forwarding.isWriteCacheDirtyForTable("docs"));

    forwarding_cache.evictOldestTable();
    try std.testing.expect(owner.isWriteCacheDirtyForTable("docs"));

