    try std.testing.expect(!owner.isWriteCacheDirtyForTable("docs"));

    forwarding.markWriteCacheDirty("docs");
    forwarding.clearDirtyWriteTable("docs");
    try std.testing.expect(!owner.isWriteCacheDirtyForTable("docs"));
}

