        io_impl.io().sleep(Io.Duration.fromMilliseconds(1), .awake) catch {};
    }

    const deinit_start_ns = platform_time.monotonicNs();
    source.deinit();
    const deinit_elapsed_ns = platform_time.monotonicNs() -| deinit_start_ns;
