                return .{ .status = 200, .body = try alloc_inner.dupe(u8, "{\"matched\":2,\"staged\":1,\"returning\":[{\"id\":\"z\",\"status\":\"claimed\"}],\"participant_predicates\":[{\"key\":\"row:z\",\"expected_version\":11}]}") };
            }
