}

test "write cache retirement is allocation-free after entry installation" {
    var failing = std.testing.FailingAllocator.init(std.testing.allocator, .{});
    const alloc = failing.allocator();

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

